{"file_text": "@namespace sv_d19b5822f8c54801a910f9266f2f7cf7.Components.Pages.Apply

<h4 class="mb-3">Cover Letter</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="mb-3">
    <textarea class="form-control" rows="12" value="@CoverLetter"
              @oninput="HandleInput"
              maxlength="@MaxLength"></textarea>
    <div class="form-text text-end">
        @(CoverLetter?.Length ?? 0) / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">&larr; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public int MaxLength { get; set; } = 2000;
    [Parameter] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? string.Empty;
        if (value.Length > MaxLength)
            value = value[..MaxLength];
        OnCoverLetterChanged.InvokeAsync(value);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "A cover letter is required.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
