@namespace sv_d19b5822f8c54801a910f9266f2f7cf7.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="text-center flex-fill position-relative">
                @if (isCompleted)
                {
                    <button class="btn p-0 border-0 d-flex flex-column align-items-center w-100"
                            @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="rounded-circle d-inline-flex align-items-center justify-content-center bg-success text-white"
                              style="width:36px;height:36px;">
                            <span>&#10003;</span>
                        </span>
                        <small class="mt-1 text-success fw-semibold">@StepNames[stepIndex]</small>
                    </button>
                }
                else if (isCurrent)
                {
                    <div class="d-flex flex-column align-items-center">
                        <span class="rounded-circle d-inline-flex align-items-center justify-content-center bg-primary text-white fw-bold"
                              style="width:36px;height:36px;">
                            @(stepIndex + 1)
                        </span>
                        <small class="mt-1 text-primary fw-semibold">@StepNames[stepIndex]</small>
                    </div>
                }
                else
                {
                    <div class="d-flex flex-column align-items-center">
                        <span class="rounded-circle d-inline-flex align-items-center justify-content-center bg-secondary bg-opacity-25 text-muted"
                              style="width:36px;height:36px;">
                            @(stepIndex + 1)
                        </span>
                        <small class="mt-1 text-muted">@StepNames[stepIndex]</small>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_d19b5822f8c54801a910f9266f2f7cf7.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="mb-0">Position @Index</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input class="form-control" value="@Entry.Company"
                       @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input class="form-control" value="@Entry.Title"
                       @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@FormatDate(Entry.StartDate)"
                       @onchange="e => Update(Entry with { StartDate = ParseDate(e.Value) })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@FormatDate(Entry.EndDate)"
                       disabled="@IsCurrent"
                       @onchange="e => Update(Entry with { EndDate = ParseNullableDate(e.Value) })" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"current-{Index}")"
                           checked="@IsCurrent"
                           @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"current-{Index}")">Currently work here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Entry.Description"
                          @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }

    private static string FormatDate(DateTime date) =>
        date == default ? string.Empty : date.ToString("yyyy-MM-dd");

    private static string FormatDate(DateTime? date) =>
        date?.ToString("yyyy-MM-dd") ?? string.Empty;

    private static DateTime ParseDate(object? value) =>
        DateTime.TryParse(value?.ToString(), out var d) ? d : default;

    private static DateTime? ParseNullableDate(object? value) =>
        DateTime.TryParse(value?.ToString(), out var d) ? d : null;
}

