@namespace sv_d19b5822f8c54801a910f9266f2f7cf7.Components.Pages.Apply

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="References[index]"
                   Index="index + 1"
                   CanRemove="References.Count > 2"
                   OnChanged="r => UpdateReference(index, r)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">&larr; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = [];
    [Parameter] public EventCallback<List<Reference>> OnReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, Reference updated)
    {
        var list = new List<Reference>(References);
        list[index] = updated;
        OnReferencesChanged.InvokeAsync(list);
    }

    private void RemoveReference(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnReferencesChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new(string.Empty, string.Empty, string.Empty, string.Empty)
        };
        OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Count < 2)
        {
            ErrorMessage = "At least 2 references are required.";
            return;
        }

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) ||
                                string.IsNullOrWhiteSpace(r.Relationship) ||
                                string.IsNullOrWhiteSpace(r.Email) ||
                                string.IsNullOrWhiteSpace(r.Phone)))
        {
            ErrorMessage = "All reference fields are required.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

