toolArgs.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_d19b5822f8c54801a910f9266f2f7cf7.Models
@using sv_d19b5822f8c54801a910f9266f2f7cf7.Components.Pages.Apply
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   StepNames="_stepNames"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Model="_personal"
                                  OnModelChanged="p => _personal = p"
                                  OnNext="() => GoToStep(1)"
                                  ValidateEmail="AppService.ValidateEmailAsync" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnEntriesChanged="e => _workEntries = e"
                                 OnNext="() => GoToStep(2)"
                                 OnBack="() => GoToStep(0)" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                OnReferencesChanged="r => _references = r"
                                OnNext="() => GoToStep(3)"
                                OnBack="() => GoToStep(1)" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="_coverLetter"
                                 OnCoverLetterChanged="c => _coverLetter = c"
                                 OnNext="() => GoToStep(4)"
                                 OnBack="() => GoToStep(2)" />
                break;

            case 4:
                <ReviewStep Personal="_personal"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="_coverLetter"
                            OnEditSection="GoToStep"
                            OnBack="() => GoToStep(3)"
                            OnSubmit="SubmitAsync" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep;

    private static readonly IReadOnlyList<string> _stepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private PersonalInfo _personal = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> _workEntries = [new(string.Empty, string.Empty, default, null, string.Empty)];
    private List<Reference> _references =
    [
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    ];
    private string _coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step < _currentStep || step == _currentStep + 1)
            _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter);

        return await AppService.SubmitApplicationAsync(application);
    }
}

